/**
 * The NRBF reader: walks a .NET binary-serialized stream record by record and builds the object
 * tree it describes.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    NrbfValue, BinaryObject, NRBFReader
 * depends    src/node/nrbf/types
 * used by    src/node/decode-save, src/node/nrbf/index, src/save-decoder/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import { BinaryArrayType, BinaryType, PrimitiveType, RecordType } from './types'

class BinaryReader {
  private position = 0
  private view: DataView
  constructor(private buffer: Uint8Array) {
    this.view = new DataView(buffer.buffer, buffer.byteOffset, buffer.byteLength)
  }

  requireBytes(length: number): void {
    if (!Number.isSafeInteger(length) || length < 0 || length > this.buffer.length - this.position) {
      throw new RangeError('Incomplete NRBF data at byte ' + this.position)
    }
  }
  private take(length: number): number {
    this.requireBytes(length)
    const start = this.position
    this.position += length
    return start
  }
  readByte(): number { return this.view.getUint8(this.take(1)) }
  readSByte(): number { return this.view.getInt8(this.take(1)) }
  readBoolean(): boolean { return this.readByte() !== 0 }
  readInt16(): number { return this.view.getInt16(this.take(2), true) }
  readUInt16(): number { return this.view.getUint16(this.take(2), true) }
  readInt32(): number { return this.view.getInt32(this.take(4), true) }
  readUInt32(): number { return this.view.getUint32(this.take(4), true) }
  readInt64(): bigint { return this.view.getBigInt64(this.take(8), true) }
  readUInt64(): bigint { return this.view.getBigUint64(this.take(8), true) }
  readSingle(): number { return this.view.getFloat32(this.take(4), true) }
  readDouble(): number { return this.view.getFloat64(this.take(8), true) }
  readLength(): number {
    const length = this.readInt32()
    if (length < 0) throw new Error('Invalid negative NRBF length')
    return length
  }
  readChar(): string {
    const code = this.readUInt16()
    return String.fromCharCode(code)
  }

  readString(): string {
    let length = 0
    for (let index = 0; index < 5; index++) {
      const byte = this.readByte()
      if (index === 4 && byte > 7) throw new Error('Invalid NRBF string length')
      length += (byte & 0x7F) * 2 ** (index * 7)
      if ((byte & 0x80) !== 0) continue
      this.requireBytes(length)
      const bytes = this.buffer.subarray(this.position, this.position + length)
      this.position += length
      return new TextDecoder('utf-8').decode(bytes)
    }
    throw new Error('Invalid NRBF string length')
  }
}

type DeferredReference = { id: number }

/**
 * Everything an NRBF stream can decode to.
 *
 * The format reconstructs arbitrary .NET object graphs, so a reader for it is
 * genuinely dynamic — but "dynamic" here has a shape: a primitive, an object
 * with named members, an array of those, or a reference to one not yet read.
 * Naming that is worth more than `any`, because it makes a caller narrow
 * before it can read a member off whatever came back.
 */
export type NrbfValue =
  | BinaryObject
  | NrbfValue[]
  | string
  | number
  | boolean
  | bigint
  | Date
  | DeferredReference
  /** A run of nulls, which the format encodes as a count rather than repeats. */
  | { nullCount: number }
  | ClassSerializationRecord
  | null
  | undefined

export class BinaryObject {
  private m = new Map<string, NrbfValue>()
  typeName = ''
  get entries(): IterableIterator<[string, NrbfValue]> { return this.m.entries() }
  addMember(n: string, v: NrbfValue): void { this.m.set(n, v) }
}

type ClassInfo = { objectId: number; name: string; memberCount: number; memberNames: string[] }
const readClassInfo = (r: BinaryReader): ClassInfo => {
  const objectId = r.readInt32()
  const name = r.readString()
  const memberCount = r.readLength()
  r.requireBytes(memberCount)
  return { objectId, name, memberCount, memberNames: Array.from({ length: memberCount }, () => r.readString()) }
}

interface ClassSerializationRecord {
  classInfo?: ClassInfo;
  memberTypeInfo?: MemberTypeInfo;
  value?: BinaryObject;
}

type MemberTypeInfo = { binaryType: BinaryType[]; additionalInfos: PrimitiveType[] }
const readMemberTypeInfo = (count: number, r: BinaryReader): MemberTypeInfo => {
  const binaryType = Array.from({ length: count }, () => r.readByte() as BinaryType)
  const additionalInfos: PrimitiveType[] = []
  for (let i = 0; i < count; i++) {
    const bt = binaryType[i]
    if (bt === BinaryType.Primitive || bt === BinaryType.PrimitiveArray) additionalInfos[i] = r.readByte() as PrimitiveType
    else if (bt === BinaryType.SystemClass || bt === BinaryType.Class) { r.readString(); if (bt === BinaryType.Class) r.readInt32() }
  }
  return { binaryType, additionalInfos }
}

type ArrayInfo = { objectId: number; length: number }
const readArrayInfo = (r: BinaryReader): ArrayInfo => ({ objectId: r.readInt32(), length: r.readLength() })

const readHeader = (r: BinaryReader): number => {
  const rootId = r.readInt32()
  r.readInt32()
  if (r.readInt32() !== 1 || r.readInt32() !== 0) throw new Error('Invalid NRBF stream')
  return rootId
}

const readTimeSpan = (r: BinaryReader) => Number(r.readInt64()) / 10000
const readDateTime = (r: BinaryReader) => new Date(Number(((r.readInt64() & 0x3FFFFFFFFFFFFFFFn) - 621355968000000000n) / 10000n))
const readPrimitive = (type: PrimitiveType, r: BinaryReader): NrbfValue => {
  const m: Partial<Record<PrimitiveType, () => NrbfValue>> = {
    [PrimitiveType.Boolean]: () => r.readBoolean(), [PrimitiveType.Byte]: () => r.readByte(), [PrimitiveType.Char]: () => r.readChar(),
    [PrimitiveType.Double]: () => r.readDouble(), [PrimitiveType.Int16]: () => r.readInt16(), [PrimitiveType.Int32]: () => r.readInt32(),
    [PrimitiveType.Int64]: () => r.readInt64(), [PrimitiveType.SByte]: () => r.readSByte(), [PrimitiveType.Single]: () => r.readSingle(),
    [PrimitiveType.UInt16]: () => r.readUInt16(), [PrimitiveType.UInt32]: () => r.readUInt32(), [PrimitiveType.UInt64]: () => r.readUInt64(),
    [PrimitiveType.Decimal]: () => parseFloat(r.readString()), [PrimitiveType.TimeSpan]: () => readTimeSpan(r), [PrimitiveType.DateTime]: () => readDateTime(r),
  }
  const fn = m[type]
  if (!fn) throw new Error('Invalid primitive type: ' + PrimitiveType[type])
  return fn()
}
type BinaryArrayRecord = { objectId: number; binaryArrayType: BinaryArrayType; rank: number; lengths: number[]; lowerBounds?: number[]; binaryType: BinaryType; primitiveType: PrimitiveType }
const readBinaryArrayRecord = (r: BinaryReader): BinaryArrayRecord => {
  const objectId = r.readInt32()
  const binaryArrayType = r.readByte() as BinaryArrayType
  const rank = r.readLength()
  if (rank === 0) throw new Error('Invalid NRBF array rank')
  r.requireBytes(rank * 4)
  const lengths = Array.from({ length: rank }, () => r.readLength())
  const lowerBounds = [BinaryArrayType.SingleOffset, BinaryArrayType.JaggedOffset, BinaryArrayType.RectangularOffset].includes(binaryArrayType)
    ? Array.from({ length: rank }, () => r.readInt32()) : undefined
  const binaryType = r.readByte() as BinaryType
  let primitiveType = PrimitiveType.None
  if (binaryType === BinaryType.Primitive || binaryType === BinaryType.PrimitiveArray) {
    primitiveType = r.readByte() as PrimitiveType
  } else if (binaryType === BinaryType.SystemClass || binaryType === BinaryType.Class) {
    r.readString()
    if (binaryType === BinaryType.Class) r.readInt32()
  }
  return { objectId, binaryArrayType, rank, lengths, lowerBounds, binaryType, primitiveType }
}

interface DeferredItem {
  owner?: BinaryObject;
  member?: string;
  id: number;
  deferredAction?: (value: NrbfValue) => void;
}

export class NRBFReader {
  private reader: BinaryReader
  private endOfStream = false
  private objectsById = new Map<number, NrbfValue>()
  private deferredItems: DeferredItem[] = []

  private constructor(buffer: Uint8Array) {
    this.reader = new BinaryReader(buffer)
  }

  public static readStream(buffer: Uint8Array): NrbfValue {
    return new NRBFReader(buffer).parse()
  }

  private parse(): NrbfValue {
    if (this.reader.readByte() !== RecordType.SerializedStreamHeader) throw new Error('Invalid NRBF stream')
    const rootId = readHeader(this.reader)
    while (!this.endOfStream) this.readWithRecordType(true)
    this.completeDeferredItems()
    return this.dereferenceTrackedObject(rootId)
  }

  private read = (): NrbfValue => this.readWithRecordType().value

  private readWithRecordType(allowMessageEnd = false): { value: NrbfValue; recordType: RecordType } {
    let currentObject: NrbfValue = null
    const recordType = this.reader.readByte() as RecordType

    switch (recordType) {
      case RecordType.ClassWithId:
      case RecordType.SystemClassWithMembers:
      case RecordType.ClassWithMembers:
      case RecordType.SystemClassWithMembersAndTypes:
      case RecordType.ClassWithMembersAndTypes:
        currentObject = this.readClassRecord(recordType)
        break

      case RecordType.BinaryObjectString:
        {
          const id = this.reader.readInt32()
          currentObject = this.reader.readString()
          if (id !== 0) this.objectsById.set(id, currentObject)
        }
        break

      case RecordType.BinaryArray:
        {
          const br = readBinaryArrayRecord(this.reader)
          currentObject = this.readBinaryArray(br)
          if (br.objectId !== 0) this.objectsById.set(br.objectId, currentObject)
        }
        break

      case RecordType.MemberPrimitiveTyped:
        currentObject = readPrimitive(this.reader.readByte() as PrimitiveType, this.reader)
        break

      case RecordType.MemberReference:
        {
          const id = this.reader.readInt32()
          const ref = this.objectsById.get(id)
          currentObject = ref === undefined ? { id } as DeferredReference :
            (ref && typeof ref === 'object' && 'value' in ref ? (ref as ClassSerializationRecord).value : ref)
        }
        break

      case RecordType.ObjectNull:
        return { value: null, recordType }

      case RecordType.MessageEnd:
        if (!allowMessageEnd) throw new Error('Unexpected NRBF MessageEnd inside a value')
        this.endOfStream = true
        break

      case RecordType.BinaryLibrary:
        this.reader.readInt32()
        this.reader.readString()
        break

      case RecordType.ObjectNullMultiple256:
      case RecordType.ObjectNullMultiple:
        currentObject = { nullCount: recordType === RecordType.ObjectNullMultiple256 ? this.reader.readByte() : this.reader.readInt32() }
        break

      case RecordType.ArraySinglePrimitive:
      case RecordType.ArraySingleObject:
      case RecordType.ArraySingleString:
        currentObject = this.readSingleArrayRecord(recordType)
        break

      case RecordType.MethodCall:
      case RecordType.MethodReturn:
      case RecordType.SerializedStreamHeader:
      default:
        throw new Error('RecordType not supported: ' + RecordType[recordType])
    }

    return { value: currentObject, recordType }
  }

  private readMembers(o: BinaryObject, mns: string[], mti: MemberTypeInfo): void {
    for (let i = 0; i < mns.length; i++) {
      if (mti.binaryType[i] === BinaryType.Primitive) {
        o.addMember(mns[i], readPrimitive(mti.additionalInfos[i] as PrimitiveType, this.reader))
      } else {
        const mc = this.read()
        if (mc && typeof mc === 'object' && 'id' in mc) {
          this.deferredItems.push({ owner: o, member: mns[i], id: (mc as DeferredReference).id })
          o.addMember(mns[i], null)
        } else o.addMember(mns[i], mc)
      }
    }
  }

  private readUntypedMembers(o: BinaryObject, cn: string, mns: string[]): void {
    if (cn === 'System.Guid' && mns.length === 11) {
      o.addMember('_a', this.reader.readInt32())
      o.addMember('_b', this.reader.readInt16())
      o.addMember('_c', this.reader.readInt16());
      ['_d', '_e', '_f', '_g', '_h', '_i', '_j', '_k'].forEach(m => o.addMember(m, this.reader.readByte()))
      return
    }
    if (mns.length === 1 && mns[0] === 'value__') { o.addMember(mns[0], this.reader.readInt32()); return }
    throw new Error('Unsupported untyped member: ' + cn)
  }

  /**
   * The three single-dimension array records, which differ only in how their
   * elements are read and otherwise share the header and the tracking.
   */
  /**
   * The five class records.
   *
   * They differ in whether the type info is inline, referenced from an
   * earlier record, or absent — and in whether a library id follows — but
   * all five produce a `BinaryObject` and register it for later references.
   */
  private readClassRecord(recordType: RecordType): NrbfValue {
    let value: NrbfValue = null
    switch (recordType) {
      case RecordType.ClassWithId:
        {
          const oid = this.reader.readInt32()
          const ref = this.objectsById.get(this.reader.readInt32()) as ClassSerializationRecord
          if (!ref?.classInfo || !ref.value) throw new Error('Missing NRBF class metadata')
          const o = Object.assign(new BinaryObject(), { typeName: ref.value!.typeName })
          if (oid !== 0) this.objectsById.set(oid, o)
          value = o
          if (ref.memberTypeInfo) {
            this.readMembers(o, ref.classInfo!.memberNames, ref.memberTypeInfo)
          } else {
            this.readUntypedMembers(o, o.typeName, ref.classInfo!.memberNames)
          }
        }
        break

      case RecordType.SystemClassWithMembers:
      case RecordType.ClassWithMembers:
        {
          const ci = readClassInfo(this.reader)
          if (recordType === RecordType.ClassWithMembers) this.reader.readInt32()
          const v = Object.assign(new BinaryObject(), { typeName: ci.name })
          const res: ClassSerializationRecord = { classInfo: ci, value: v }
          if (ci.objectId !== 0) this.objectsById.set(ci.objectId, res)
          value = v
          this.readUntypedMembers(v, ci.name, ci.memberNames)
        }
        break

      case RecordType.SystemClassWithMembersAndTypes:
      case RecordType.ClassWithMembersAndTypes:
        {
          const ci = readClassInfo(this.reader)
          const mti = readMemberTypeInfo(ci.memberCount, this.reader)
          if (recordType === RecordType.ClassWithMembersAndTypes) this.reader.readInt32()
          const v = Object.assign(new BinaryObject(), { typeName: ci.name })
          const res: ClassSerializationRecord = { classInfo: ci, memberTypeInfo: mti, value: v }
          if (ci.objectId !== 0) this.objectsById.set(ci.objectId, res)
          value = v
          this.readMembers(v, ci.memberNames, mti)
        }
        break

      default:
        throw new Error('RecordType not supported: ' + RecordType[recordType])
    }
    return value
  }

  private readSingleArrayRecord(recordType: RecordType): NrbfValue {
    const info = readArrayInfo(this.reader)
    const value = recordType === RecordType.ArraySinglePrimitive
      ? this.readPrimitiveArray(info, this.reader.readByte() as PrimitiveType)
      : this.readObjectArray(info, recordType === RecordType.ArraySingleString)

    if (info.objectId !== 0) this.objectsById.set(info.objectId, value)
    return value
  }

  private readPrimitiveArray(info: ArrayInfo, type: PrimitiveType): NrbfValue[] {
    const values: NrbfValue[] = []
    for (let i = 0; i < info.length; i++) values.push(readPrimitive(type, this.reader))
    return values
  }

  private readObjectArray(info: ArrayInfo, stringsOnly = false): NrbfValue[] {
    const r: NrbfValue[] = []
    const set = (index: number, value: NrbfValue): void => {
      if (stringsOnly && value !== null && typeof value !== 'string') throw new Error('Invalid NRBF string array element')
      r[index] = value
    }
    for (let i = 0; i < info.length; i++) {
      const rr = this.readWithRecordType()
      const v = rr.recordType === RecordType.BinaryLibrary ? this.read() : rr.value
      if (v && typeof v === 'object' && 'nullCount' in v) {
        const count = v.nullCount
        if (count <= 0 || count > info.length - i) throw new Error('Invalid NRBF null run length')
        for (let j = 0; j < count; j++) r[i + j] = null
        i += count - 1
      }
      else if (v && typeof v === 'object' && 'id' in v) {
        const idx = i
        this.deferredItems.push({ id: (v as DeferredReference).id, deferredAction: res => set(idx, res) })
      } else set(i, v)
    }
    return r
  }

  private readBinaryArray(r: BinaryArrayRecord): NrbfValue {
    const size = r.lengths.reduce((total, length) => total * length, 1)
    if (!Number.isSafeInteger(size)) throw new Error('Invalid NRBF array size')
    const createArray = (d: number[], l?: number[]): NrbfValue => d.length === 1
      ? (() => { const a: NrbfValue[] = []; const lb = l ? l[0] : 0; for (let i = 0; i < d[0]; i++) a[lb + i] = null; return a })()
      : (() => { const a: NrbfValue[] = []; const lb = l ? l[0] : 0; for (let i = 0; i < d[0]; i++) a[lb + i] = createArray(d.slice(1), l?.slice(1)); return a })()
    const res = createArray(r.lengths, r.lowerBounds)
    if (size === 0) return res
    const firstIdx = (d: number[], l?: number[]): number[] => d.map((_, i) => l ? l[i] : 0)
    const nextIdx = (idx: number[], d: number[], l?: number[]): number[] | null => {
      for (let i = idx.length - 1; i >= 0; --i) {
        idx[i]++
        if (idx[i] <= (l ? l[i] : 0) + d[i] - 1) return idx
        idx[i] = l ? l[i] : 0
      }
      return null
    }
    /**
     * Write into a jagged array by index path.
     *
     * The intermediate levels are arrays because `createArray` just built them
     * that way, which is knowledge the type cannot carry on its own.
     */
    const setVal = (a: NrbfValue, idx: number[], v: NrbfValue): void => {
      let c = a as NrbfValue[]
      for (let i = 0; i < idx.length - 1; i++) c = c[idx[i]] as NrbfValue[]
      c[idx[idx.length - 1]] = v
    }

    if (r.primitiveType === PrimitiveType.None || r.binaryArrayType === BinaryArrayType.Jagged) {
      if (r.binaryType !== BinaryType.Primitive) {
        let cc = 0
        let remaining = size
        let idx: number[] | null = firstIdx(r.lengths, r.lowerBounds)
        while (idx !== null) {
          if (cc > 0) { cc--; remaining--; idx = nextIdx(idx!, r.lengths, r.lowerBounds); continue }
          const rr = this.readWithRecordType()
          const v = rr.recordType === RecordType.BinaryLibrary ? this.read() : rr.value
          if (v && typeof v === 'object' && 'nullCount' in v) {
            if (v.nullCount <= 0 || v.nullCount > remaining) throw new Error('Invalid NRBF null run length')
            cc = v.nullCount - 1
          }
          else if (v && typeof v === 'object' && 'id' in v) {
            const si = [...idx]
            this.deferredItems.push({ id: (v as DeferredReference).id, deferredAction: rv => setVal(res, si, rv) })
          } else setVal(res, idx, v)
          remaining--
          idx = nextIdx(idx, r.lengths, r.lowerBounds)
        }
      } else throw new Error('Unsupported array structure')
    } else {
      let idx: number[] | null = firstIdx(r.lengths, r.lowerBounds)
      while (idx !== null) {
        setVal(res, idx, readPrimitive(r.primitiveType, this.reader))
        idx = nextIdx(idx, r.lengths, r.lowerBounds)
      }
    }
    return res
  }

  private completeDeferredItems(): void {
    for (const it of this.deferredItems) {
      const ref = this.dereferenceTrackedObject(it.id)
      if (it.deferredAction) it.deferredAction(ref)
      else if (it.owner && it.member !== undefined) it.owner.addMember(it.member, ref)
    }
  }

  private dereferenceTrackedObject(id: number): NrbfValue {
    if (!this.objectsById.has(id)) throw new Error('Unresolved NRBF object reference: ' + id)
    const ref = this.objectsById.get(id)
    return (ref && typeof ref === 'object' && 'value' in ref) ? (ref as ClassSerializationRecord).value : ref
  }
}
